-- Módulo 63 AsistenciaBiometrica: marcaciones del reloj o manuales y jornadas de asistencia calculadas.
-- Spec: docs/specs/modulo63-asistencia-biometrica-backend.md (§4).

CREATE TABLE "Marcaciones" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "Tipo" character varying(10) NOT NULL,
    "Instante" timestamp with time zone NOT NULL,
    "Origen" character varying(10) NOT NULL,
    "Dispositivo" character varying(50),
    "NumeroRegistro" character varying(50),
    "Observacion" character varying(200),
    CONSTRAINT "PK_Marcaciones" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Marcaciones_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_Marcaciones_Tipo" CHECK ("Tipo" IN ('Entrada', 'Salida')),
    CONSTRAINT "CK_Marcaciones_Origen" CHECK ("Origen" IN ('Reloj', 'Manual'))
);
CREATE INDEX "IX_Marcaciones_EmpleadoId_Instante" ON "Marcaciones" ("EmpleadoId", "Instante");
-- A3: la importación es idempotente por dispositivo y número de registro (las manuales tienen ambos nulos).
CREATE UNIQUE INDEX "IX_Marcaciones_Dispositivo_NumeroRegistro" ON "Marcaciones" ("Dispositivo", "NumeroRegistro");

CREATE TABLE "JornadasAsistencia" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "Fecha" date NOT NULL,
    "TurnoId" integer,
    "HoraEntradaProgramada" time without time zone,
    "HoraSalidaProgramada" time without time zone,
    "ToleranciaMinutos" integer NOT NULL,
    "Entrada" timestamp with time zone,
    "Salida" timestamp with time zone,
    "MinutosTrabajados" integer NOT NULL,
    "MinutosTardanza" integer NOT NULL,
    "MinutosExtra" integer NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "EstadoHorasExtra" character varying(20) NOT NULL,
    "DecididoPor" character varying(100),
    "FechaDecision" timestamp with time zone,
    "MotivoRechazo" character varying(300),
    CONSTRAINT "PK_JornadasAsistencia" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_JornadasAsistencia_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_JornadasAsistencia_Turnos_TurnoId" FOREIGN KEY ("TurnoId") REFERENCES "Turnos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_JornadasAsistencia_Estado" CHECK ("Estado" IN ('Asistencia', 'Tardanza', 'SinMarcacion', 'Falta', 'DescansoTrabajado')),
    CONSTRAINT "CK_JornadasAsistencia_EstadoHorasExtra" CHECK ("EstadoHorasExtra" IN ('NoAplica', 'Pendiente', 'Aprobada', 'Rechazada'))
);
CREATE INDEX "IX_JornadasAsistencia_TurnoId" ON "JornadasAsistencia" ("TurnoId");
CREATE UNIQUE INDEX "IX_JornadasAsistencia_EmpleadoId_Fecha" ON "JornadasAsistencia" ("EmpleadoId", "Fecha");
